// Gota · package API (dist/index.js): the core (./core.js) plus the whole set by name. Each icon's
// data comes from ./data.js (generated by scripts/build.mjs). To carry only the icons a page uses,
// import them from @flouvia/gota/icons and draw them with the core instead.
import { svg } from './core.js';
import { categories, icons } from './data.js';

export * from './core.js';
export { categories, icons };

const linked = new Map();
/**
 * An icon's data by name, with its name and its hand-drawn variants linked (`drawn`): the same shape
 * as a module of @flouvia/gota/icons. Undefined if there is no such icon.
 */
export function iconData(name) {
  if (!icons[name]) return undefined;
  if (!linked.has(name)) {
    const slash = icons[`${name}-slash`] ? `${name}-slash` : icons[`${name}-off`] ? `${name}-off` : null;
    const drawn = Object.fromEntries(
      [
        ['circle', icons[`${name}-circle`] && `${name}-circle`],
        ['square', icons[`${name}-square`] && `${name}-square`],
        ['slash', slash],
      ]
        .filter(([, n]) => n)
        .map(([k, n]) => [k, iconData(n)]),
    );
    linked.set(name, { name, ...icons[name], ...(Object.keys(drawn).length && { drawn }) });
  }
  return linked.get(name);
}

/** If the variant exists as a hand-drawn icon (arrow-right-circle, bell-off…), it wins over the automatic one. */
export function resolveIcon(name, { enclosure = null, slash = false } = {}) {
  if (enclosure && icons[`${name}-${enclosure}`]) return { name: `${name}-${enclosure}`, enclosure: null, slash };
  if (slash && (icons[`${name}-slash`] || icons[`${name}-off`])) return { name: icons[`${name}-slash`] ? `${name}-slash` : `${name}-off`, enclosure, slash: false };
  return { name, enclosure, slash };
}

/**
 * The complete SVG of an icon by name:
 * toSvg('bell', { variant: 'fill', weight: 'bold', enclosure: 'circle', slash: true, size: 16 })
 * toSvg('bell', { animate: 'auto', play: 'hover' })   // with engine/motion.css (./motion.css)
 */
export function toSvg(name, options = {}) {
  return svg(iconData(name), { id: name, ...options });
}
